// Package compose generates docker compose files and drives the compose CLI.
// Every resource Pier runs (application, database, stack, proxy) is a compose
// project, which keeps a single execution path.
package compose

import (
	"strings"

	"gopkg.in/yaml.v3"
)

// File is a compose document generated by Pier.
type File struct {
	Services map[string]*Service `yaml:"services"`
	Networks map[string]*Network `yaml:"networks,omitempty"`
	Volumes  map[string]*Volume  `yaml:"volumes,omitempty"`
}

// Service is one container definition.
type Service struct {
	StopGracePeriod string `yaml:"stop_grace_period,omitempty"`
	Image         string                        `yaml:"image"`
	ContainerName string                        `yaml:"container_name,omitempty"`
	Restart       string                        `yaml:"restart,omitempty"`
	Command       []string                      `yaml:"command,omitempty"`
	Environment   map[string]string             `yaml:"environment,omitempty"`
	Labels        map[string]string             `yaml:"labels,omitempty"`
	Volumes       []string                      `yaml:"volumes,omitempty"`
	Ports         []string                      `yaml:"ports,omitempty"`
	Networks      map[string]*NetworkAttachment `yaml:"networks,omitempty"`
	Healthcheck   *Healthcheck                  `yaml:"healthcheck,omitempty"`
	CPUs          string                        `yaml:"cpus,omitempty"`
	MemLimit      string                        `yaml:"mem_limit,omitempty"`
	ExtraHosts    []string                      `yaml:"extra_hosts,omitempty"`
	Privileged    bool                          `yaml:"privileged,omitempty"`
	Tmpfs         []string                      `yaml:"tmpfs,omitempty"`
	Logging       *Logging                      `yaml:"logging,omitempty"`
	// Validated application Docker options (application/docker_options.go).
	CapAdd      []string          `yaml:"cap_add,omitempty"`
	CapDrop     []string          `yaml:"cap_drop,omitempty"`
	Ulimits     map[string]Ulimit `yaml:"ulimits,omitempty"`
	ShmSize     string            `yaml:"shm_size,omitempty"`
	Devices     []string          `yaml:"devices,omitempty"`
	NetworkMode string            `yaml:"network_mode,omitempty"`
	Pid         string            `yaml:"pid,omitempty"`
}

// Ulimit mirrors one entry of the compose ulimits block.
type Ulimit struct {
	Soft int64 `yaml:"soft"`
	Hard int64 `yaml:"hard"`
}

// Logging mirrors the compose logging block.
type Logging struct {
	Driver  string            `yaml:"driver,omitempty"`
	Options map[string]string `yaml:"options,omitempty"`
}

// DefaultLogging rotates container logs so a chatty service cannot fill the
// server's disk: the "local" driver keeps at most three files of 10 MB.
func DefaultLogging() *Logging {
	return &Logging{Driver: "local", Options: map[string]string{"max-size": "10m", "max-file": "3"}}
}

// NetworkAttachment configures how a service joins a network.
type NetworkAttachment struct {
	Aliases []string `yaml:"aliases,omitempty"`
}

// Network declares a network used by the project.
type Network struct {
	Name     string `yaml:"name,omitempty"`
	External bool   `yaml:"external,omitempty"`
}

// Volume declares a named volume.
type Volume struct {
	Name string `yaml:"name,omitempty"`
}

// Healthcheck mirrors the compose healthcheck block.
type Healthcheck struct {
	Test        []string `yaml:"test"`
	Interval    string   `yaml:"interval,omitempty"`
	Timeout     string   `yaml:"timeout,omitempty"`
	Retries     int      `yaml:"retries,omitempty"`
	StartPeriod string   `yaml:"start_period,omitempty"`
}

// Marshal renders the YAML. Generated files never rely on compose variable
// interpolation, so every "$" is escaped to keep values literal. A service
// without its own logging block gets DefaultLogging.
func (f *File) Marshal() ([]byte, error) {
	escaped := File{Services: make(map[string]*Service, len(f.Services)), Networks: f.Networks, Volumes: f.Volumes}
	for name, service := range f.Services {
		clone := *service
		clone.Environment = escapeMap(service.Environment)
		clone.Labels = escapeMap(service.Labels)
		clone.Command = escapeSlice(service.Command)
		if clone.Logging == nil {
			clone.Logging = DefaultLogging()
		}
		if service.Healthcheck != nil {
			healthcheck := *service.Healthcheck
			healthcheck.Test = escapeSlice(service.Healthcheck.Test)
			clone.Healthcheck = &healthcheck
		}
		escaped.Services[name] = &clone
	}
	return yaml.Marshal(escaped)
}

// EscapeInterpolation makes a value literal for compose ("$" becomes "$$").
func EscapeInterpolation(value string) string { return strings.ReplaceAll(value, "$", "$$") }

func escapeMap(values map[string]string) map[string]string {
	if values == nil {
		return nil
	}
	escaped := make(map[string]string, len(values))
	for key, value := range values {
		escaped[key] = EscapeInterpolation(value)
	}
	return escaped
}

func escapeSlice(values []string) []string {
	if values == nil {
		return nil
	}
	escaped := make([]string, len(values))
	for i, value := range values {
		escaped[i] = EscapeInterpolation(value)
	}
	return escaped
}
